#!/usr/bin/env node
/**
 * build/releases.mjs — resolves full-resolution download links from GitHub Releases.
 *
 * Runs in CI before build.mjs. For every collection whose `release` field is set,
 * lists that release's assets and writes:
 *
 *   build/release-assets.json
 *   { "<collection.dir>": { "<lowercase asset filename>": "<browser_download_url>", ... }, ... }
 *
 * Matching is case-insensitive and by filename, so previews generated by
 * scripts/previews.mjs keep the original filenames and match automatically.
 *
 * No GITHUB_TOKEN / not on GitHub Actions → writes an empty map and exits 0,
 * so local builds keep working (downloads are simply hidden until CI runs).
 * API errors (e.g. no release published yet) are non-fatal warnings.
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CONFIG_PATH = process.env.CONFIG || path.join(ROOT, "src", "config.json");
const OUT_PATH = process.env.RELEASE_ASSETS || path.join(ROOT, "build", "release-assets.json");
const API = (process.env.GITHUB_API_URL || "https://api.github.com").replace(/\/$/, "");

const log = (...a) => console.log("[releases]", ...a);

async function github(pathname) {
  const res = await fetch(`${API}${pathname}`, {
    headers: {
      Authorization: `Bearer ${process.env.GITHUB_TOKEN}`,
      Accept: "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "User-Agent": "client-gallery-ci",
    },
  });
  if (!res.ok) throw new Error(`GET ${pathname} → HTTP ${res.status}`);
  return res.json();
}

async function getJSON(file) {
  return JSON.parse(await readFile(file, "utf8"));
}

/** Fetch every asset of a release, following pagination. */
async function releaseAssets(releaseId) {
  const assets = [];
  for (let page = 1; page <= 10; page++) {
    const batch = await github(`/repos/${process.env.GITHUB_REPOSITORY}/releases/${releaseId}/assets?per_page=100&page=${page}`);
    assets.push(...batch);
    if (batch.length < 100) break;
  }
  return assets;
}

async function main() {
  await mkdir(path.dirname(OUT_PATH), { recursive: true });

  const repo = process.env.GITHUB_REPOSITORY;
  if (!repo || !process.env.GITHUB_TOKEN) {
    log("not running on GitHub Actions (or no token) — writing empty download map");
    await writeFile(OUT_PATH, "{}");
    return;
  }

  const config = await getJSON(CONFIG_PATH);
  const wanted = config.collections
    .filter((c) => c.release)
    .map((c) => ({ dir: c.dir, release: String(c.release) }));

  if (wanted.length === 0) {
    log("no collections reference a release — nothing to resolve");
    await writeFile(OUT_PATH, "{}");
    return;
  }

  const result = {};
  const tagCache = new Map(); // release tag name → { filename: url }

  for (const { dir, release } of wanted) {
    if (tagCache.has(release)) {
      result[dir] = tagCache.get(release);
      continue;
    }
    try {
      const pathname =
        release === "latest"
          ? `/repos/${repo}/releases/latest`
          : `/repos/${repo}/releases/tags/${encodeURIComponent(release)}`;
      const rel = await github(pathname);
      const map = {};
      for (const asset of await releaseAssets(rel.id)) {
        map[asset.name.toLowerCase()] = asset.browser_download_url;
      }
      tagCache.set(release, map);
      result[dir] = map;
      log(`collection "${dir}" ← release "${rel.tag_name}": ${Object.keys(map).length} asset(s)`);
    } catch (err) {
      log(`warning: ${err.message} — downloads for "${dir}" will be hidden`);
      tagCache.set(release, {});
      result[dir] = {};
    }
  }

  await writeFile(OUT_PATH, JSON.stringify(result, null, 1));
  log(`wrote ${path.relative(ROOT, OUT_PATH)}`);
}

main().catch((err) => {
  // Never fail the deploy over download links.
  console.warn("[releases] warning:", err.message, "— continuing without download links");
  writeFile(OUT_PATH, "{}").catch(() => {});
});
